INSERT INTO utente_backup VALUES(155,1676542485285,1764256348693,1,'STUDENTE','Samuele','Tonanzi','Moncalieri ','TO',1184630400000,'TNNSML07L17F335W','CA21701NZ','samuele.tonanzi@istitutoagnelli.it','3427484674','Via San Francesco 72 10042 - NICHELINO (TO)','/img/avatar.png',1,0,1,'ITT',10,NULL,0,'{"lingua_madre":"Italiano","bilingue":"NO","relazione_ssn_icd10":"\"Esiti di sofferenza perinatale\" si conferma l''indicazione all''attivazione dei Bisogni Educativi Speciali. \"Limitazioni funzionali durante l''attività motoria, quali affaticabilità, limitazione funzionale e scarsa coordinazione.\"  COMPETENZE MOTORIO-PRASSICHE: presente impaccio motorio e criticità; lieve lentezza grafo-motoria con il corsivo; scadente integrazione motoria.","relazione_ssn_redattore":"NPI Dott.ssa R. Vescovo. Diagnosi/Relazione multi professionale: ASL TO5 Chieri. ","relazione_ssn_data":"2021-05-28","relazione_ssn_aggiornamenti":"","relazione_ssn_altre":"Relazione descrittiva/diagnosi redatta da psicologa V. Muscatello in data 24/03/2020. RMN cervello e tronco encefalico in data 24/02/2021 \"esisti di pregressa sofferenza ipossico ischemica neonatale\".","relazione_ssn_interventi":"","relazione_altro_redattore1":"","relazione_altro_data1":"2025-11-27T13:54:50.770Z","relazione_altro_redattore2":"","relazione_altro_data2":"2025-11-27T13:54:50.770Z","relazione_altro_redattore3":"","relazione_altro_data3":"2025-11-27T13:54:50.770Z","relazione_altro_redattore4":"","relazione_altro_data4":"2025-11-27T13:54:50.770Z","relazione_altro_redattore5":"","relazione_altro_data5":"2025-11-27T13:54:50.770Z"}',1,NULL,0,NULL,0,NULL,0,'{"brano_velocita":"NELLA NORMA","brano_correttezza":"NELLA NORMA","parole_velocita":"NELLA NORMA ","parole_correttezza":"NELLA NORMA ","notparole_velocita":"NELLA NORMA ","notparole_correttezza":"NELLA NORMA ","lettura_altro":"","brano_cronaca":"","brano_informativo":"","brano_totale":"Sufficiente ","dettato_brano":"NELLA NORMA ","omografe":"NELLA NORMA ","lista_parole":"NELLA NORMA ","lista_notparole":"NELLA NORMA ","scrittura_altro":"","grafia_lele":"-1,6 ds ai limiti inferiori della norma ","grafia_uno":"-0,9 ds  NELLA NORMA ","grafia_numeri":"-0,7 ds NELLA NORMA ","grafia_altro":"","calcolo_area_numero":"","calcolo_conteggio":"","calcolo_lettura":"","calcolo_scrittura":"","calcolo_fatti":"","calcolo_area_calcolo":"","calcolo_moltiplicazioni":"","calcolo_mente":"","calcolo_rapido":"","calcolo_scritte":"","senso_numero":"","senso_totale":"","senso_triplette":"","senso_inserzioni":"","senso_approssimativo":"","calcolo_aritmetici":"","calcolo_altro":"Il profilo complessivo risulta superiore alla norma Quoziente totale 118 con prestazioni tutte nella norma o superiori. In particolare nell''area del numero risultano adeguate la lettura, scrittura e ripetizione numeriche, nonché il conteggio. Sul piano del calcolo, è rapido ed accurato nel recupero di fatti aritmetici in sequenza (tabelline), con ricadute positive nelle moltiplicazioni a mente. Nel calcolo a mente è rapido ed accurato, evidenziando una buona automatizzazione degli algoritmi in quello semplice (addizioni e sottrazioni; calcolo rapido) e l''uso di diverse strategie in quello complesso, seppur non sempre efficaci, tendendo a sovraccaricare la memoria di lavoro in taluni casi. Nel calcolo scritto è rapido ed accurato, dimostrando un''adeguata automatizzazione delle procedure, nonostante incolonni in modo approssimativo nel quadretto. Nell''area del senso del numero è molto rapido ed accurato sia nel riconoscimento di grandezze numeriche sia nel posizionamento lungo una linea dei numeri. E'' adeguata anche la prestazione di calcolo approssimativo, evidenziando buona abilità di stima numerica. Nonostante le brillanti prestazioni, trasversalmente a tutte le prove si osservano difficoltà di gestione emotiva dell''ansia, con drammatizzazione dell''errore e frequenti richieste di conferma sul risultato, evidenziando una tendenza al perfezionismo che ne aumenta eccessivamente il timore di sbagliare. ","altro_linguistica":"Competenze linguistiche e metafonologiche adeguate sul versante ricettivo, sia espressivo sul piano morfo-sintattico e del lessico. ","altro_memoria":"Memoria a breve termine adeguata si osservano alcune cadute nella memoria di lavoro.","altro_attenzione":"Adeguata attenzione visiva, deficitaria attenzione uditiva; non particolare affaticabilità; difficoltà di pianificazione solo del disegno, occasionale impulsività per interferenze emotive. ","altro_elaborazione":"","altro_forza":"Abilità aritmetiche superiori alla norma."}',1);
