INSERT INTO utente_backup VALUES(339,1677146966265,1758278370790,1,'STUDENTE','Daniele piero lucatoni','Villaorduna del carmen','Peru''','--',1168473600000,'VLLDLP07A11Z611U',NULL,'daniele.villaorduna@istitutoagnelli.it','3273435711','Via San Marino 118 10135 - TORINO (TO)','/img/avatar.png',0,0,1,'ITT',14,NULL,0,NULL,0,'{"mipresento_nome":"Daniele Villaorduna","mipresento_anni":17,"mipresento_classe":"3 ITT ENE","mipresento_testo_1":"mi piace la boxe, le auto, il basket e ogni tanto mi diverto a modificare alcuni codici di videogiochi o siti web.\nQui a scuola mi interessa la meccanica e impianti anche se vado male. \nle mie difficolta sono la disgrafia, a volte non riesco a vedere bene da lontano e la comprensione dell''italiano anche quando non riesco a studiare bene per i motivi di salute di mia madre ","mipresento_testo_2":"sono soddisfatto quando prendo dei bei voti e anche quando sono con gli amici","mipresento_testo_3":"non mi piace quando non riesco a fare degli schemi e poi prendo un brutto voto.\ninvece mi è di molto aiuto quando li so fare ","mipresento_testo_4":"niente solo una bella relazione","mipresento_testo_5":"meccanica, robot, basket, boxe, calcio","mipresento_testo_6":"l''anno scorso facevo MGS e quest''anno ho smesso","mipresento_testo_7":"sono molto bravo a fare delle relazioni sociali, molto generoso con gli altri, me la cavo nella maggior parte delle situazioni","mipresento_testo_8":"la pigrizia","mipresento_testo_9":"di supportarmi"}',1,'[{"qid":1,"question":"Partecipazione durante la lezione con domande e riflessioni","answers":[{"aid":"a","answer":"Non adeguata"},{"aid":"b","answer":"Poco adeguata"},{"aid":"c","answer":"Adeguata"},{"aid":"d","answer":"Molto adeguata"}],"answer":"b"},{"qid":2,"question":"Consapevolezza delle proprie difficoltà","answers":[{"aid":"a","answer":"Non adeguata"},{"aid":"b","answer":"Poco adeguata"},{"aid":"c","answer":"Adeguata"},{"aid":"d","answer":"Molto adeguata"}],"answer":"c"},{"qid":3,"question":"Consapev