INSERT INTO utente_backup VALUES(904,1726928143496,1758278328810,1,'STUDENTE','Tommaso','Alferi','Moncalieri ','TO',1288396800000,'LFRTMS10R30F335I',NULL,'tommaso.alferi@istitutoagnelli.it','3391351176','VIA ROMA 38 A 10028 - TROFARELLO (TO)',NULL,0,0,1,'ITT',3,NULL,0,NULL,0,'{"mipresento_nome":"Tommaso Alferi","mipresento_anni":14,"mipresento_classe":"1 ITT A","mipresento_testo_1":"Io mi chiamo Tommaso Alferi ho 14 anni e sono un ragazzo appassionato di scherma manga e chitarra he sono anche le mie attività preferite.","mipresento_testo_2":"Io mi sento soddisfatto quando prendo bei voti oppure faccio qualcosa bene.","mipresento_testo_3":"A me non piace studiare tantissimo ero studio il giusto siccome mi è difficile stare attento per più di tre ore.","mipresento_testo_4":"Sicuramente mi aspetto dei compagni maturi simpatici e scherzosi e degli insegnanti simpatici bravi a spiegare e che ci tengono che tu vada bene e che capisca i concetti.","mipresento_testo_5":"Io ho quattro interessi:\n-La scherma che pratico da tre anni\n-I manga che sono una mia passione da quando avevo 12 anni\n- La chitarra che è il mio interesse principale siccome la suono da quando avevo 6 anni e mi ci sono affezionato.\n-E il canto anche se non sono molto bravo. ","mipresento_testo_6":"Pratico scherma","mipresento_testo_7":"Io ho due punti di forza:\n-Il mio carattere che mi permette di andare avanti e non mollare mai.\n-la mia intelligenza anche se non la uso.","mipresento_testo_8":"Io ho una fragilità ovvero che non ho tantissima voglia di studiare anche se dovrei.","mipresento_testo_9":"Di aiutarmi nei momenti difficili."}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(905,1726928143497,1758278328811,1,'STUDENTE','Cesare','Apetroaie','Torino ','TO',1287705600000,'PTRCSR10R22L219K',NULL,'cesare.apetroaie@istitutoagnelli.it','3296153360','Via Poirino 4 10134 - TORINO (TO)',NULL,0,0,1,'ITT',3,NULL,0,NULL,0,'{"mipresento_nome":"Cesare Apetroaie","mipresento_anni":14,"mipresento_classe":"1 ITT A","mipresento_testo_1":" cesare Apetroaie, mi piace il calcio e ho difficoltà a studiare ","mipresento_testo_2":"quando faccio una buona partita o prendo un buon voto ","mipresento_testo_3":"non mi piace studiare materie in cui non trovo interesse, mi è di aiuto per studiare fare ripetizioni e mi è difficile stare per 6 ore attento a a lezione ","mipresento_testo_4":"vorrei passare l''anno con 0 materie a settembre, e mi aspetto di formare un bel gruppo con tutta la classe","mipresento_testo_5":"mi piace giocare a calcio, lo pratico da ormai 9 anni, ho giocato per 6 lunghi anni alla sisport  per poi andare al mirafiori all''inizio della seconda media. è uno sport che a mio padre,mio fratello e a me piace molto, ma diciamo che io e mio padre siamo quelli più appassionati. ogni domenica quando ero piccolo andavo con lui a giocare con la sua squadra che ha preso lo stesso nome della sua ditta.","mipresento_testo_6":"nessuno","mipresento_testo_7":"giocare a calcio, fare piccoli calcoli matematici molto veloci (addizioni sottrazione moltipicazioni e divisioni)","mipresento_testo_8":"deludere i miei genitori con voti bassi","mipresento_testo_9":"niente"}',1,NULL,1,NULL,1,NULL,0);
