INSERT INTO utente_backup VALUES(918,1726928143517,1758278328852,1,'STUDENTE','Lorenzo','Novarese','Torino ','TO',1280102400000,'NVRLNZ10L26L219I',NULL,'lorenzo.novarese@istitutoagnelli.it','3356122138','VIA MONTALE 59 10060 - CANDIOLO (TO)',NULL,0,0,1,'ITT',3,NULL,0,NULL,0,'{"mipresento_nome":"Lorenzo Novarese","mipresento_anni":14,"mipresento_classe":"1 ITTA","mipresento_testo_1":"mi chiamo lorenzo novarese ho 14 anni e gioco a calcio, sono un appassionato di motori e mi piace stare con i miei amici","mipresento_testo_2":"sono molto soddisfatto e mi sento molto bene","mipresento_testo_3":"non mi piace studiare mi è di aiuto stare attento in classe mi è difficile mantenere \n l attenzione per molto tempo","mipresento_testo_4":"vorrei non essere mai bocciato mi aspetto di essere aiutato un po dalla scuola e dai compagni mi aspetto un bel gruppo classe","mipresento_testo_5":"mi piace giocare a calcio e mi piace anche aggiustare e revisionare motorini","mipresento_testo_6":"partecipo a volte allo studio pomeridiano e anche agli sportelli che fanno i professori","mipresento_testo_7":"materie di ragionamento","mipresento_testo_8":"materie che bisogna studiare i minimi dettagli come ad esempio matematica","mipresento_testo_9":"di guardare anche l impegno che ci si mette e non solo il punteggio"}',1,NULL,1,NULL,1,NULL,0);
