INSERT INTO utente_backup VALUES(940,1726928143582,1758278328926,1,'STUDENTE','Federico','Grosso','Moncalieri ','TO',1266624000000,'GRSFRC10B20F335M',NULL,'federico.grosso@istitutoagnelli.it','3487240236','VIA ALBA 22 10040 - PRALORMO (TO)',NULL,0,0,1,'ITT',7,NULL,0,NULL,0,'{"mipresento_nome":"Federico Grosso","mipresento_anni":14,"mipresento_classe":"1TT C","mipresento_testo_1":"faccio fatica a concentrarmi, le attività preferite sono fisica e ginnastica","mipresento_testo_2":"sto benissimo","mipresento_testo_3":"Mi è di aiuto che quando un professore spiega la classe stia in silenzio,","mipresento_testo_4":"compagni giusto e simpatici","mipresento_testo_5":"sport preferito calcio","mipresento_testo_6":"oratorio a pralormo (sono animatore)","mipresento_testo_7":"essere sempre allegro","mipresento_testo_8":"\nmi abbatto dopo una insufficienza","mipresento_testo_9":"Di essere più severi "}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(941,1726928143583,1758278261281,1,'STUDENTE','Alessandro','Manassero','Torino ','TO',1288137600000,'MNSLSN10R27L219O',NULL,'alessandro.manassero@istitutoagnelli.it','3475154533','VIA SCHIFANI 16 10092 - BEINASCO (TO)',NULL,0,0,0,'ITT',1,NULL,0,NULL,0,'{"mipresento_nome":"alessandro manassero","mipresento_anni":14,"mipresento_classe":"1 ITT C","mipresento_testo_1":"io sono un ragazzo molto simpatico e gentile: i miei interessi e le mie attività preferite sono fare attività a scuola insieme a miei compagni e andare a fare esperimenti in laboratorio di chimica","mipresento_testo_2":"Quando prendo bei voti a scuola","mipresento_testo_3":"Non mi piace studiare; che alcuni miei compagni mi incoraggiano quando prendo un brutto voto; lo studio a casa","mipresento_testo_4":"che inizio a prendere bei voti; che mi aiutino se non riesco a capire delle cose","mipresento_testo_5":"I miei interessi sono stare in compagnia di parenti; il mio sport é il calcio; il mio hobby é la pesca in montagna nei fiumi e nei laghi sia artificiali sia non artificiali e andare in montagna a funghi: le attività che pratico a casa sono poche ma quelle che mi piace di più é di dare una mano a mio padre su vinted","mipresento_testo_6":"pratico calcio 4 volte a settimana","mipresento_testo_7":"Il miei principali punti di forza sono il calcio e l''amicizia con i miei compagni","mipresento_testo_8":"La voglia di studiare","mipresento_testo_9":"di aiutarmi in tutto e per tutto quando sono in difficoltà"}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(942,1726928143593,1759915811965,1,'STUDENTE','Gabriel amir lorenzo','Neri lyamini','Laval ','FRANCIA',1285545600000,'NRLGRL10P27Z110L',NULL,'gabrielamirlorenzo.nerilyamini@istitutoagnelli.it','3318979248','Via Nizza 398 10127 - TORINO (TO)',NULL,1,0,1,'ITT',7,NULL,0,NULL,0,'{"mipresento_nome":"Gabriel neri","mipresento_anni":14,"mipresento_classe":"1 itt c","mipresento_testo_1":"io sono un bambino socievole e divertente difficolta italiano","mipresento_testo_2":"quando tutta la mia famiglia sta bene","mipresento_testo_3":"non mi piace la danza mi è difficile italiano","mipresento_testo_4":"mi aspetto di farmi tanti amici perchè sono un bimbo socievole","mipresento_testo_5":"sport e hobby calcio e ping pong e calcetto(biliardino)","mipresento_testo_6":"faccio calcio","mipresento_testo_7":"giocare a calcio ","mipresento_testo_8":"mi offendo facilmente","mipresento_testo_9":"di aiutarmi nelle loro materie"}',1,'[{"qid":1,"question":"Partecipazione durante la lezione con domande e riflessioni","answers":[{"aid":"a","answer":"Non adeguata"},{"aid":"b","answer":"Poco adeguata"},{"aid":"c","answer":"Adeguata"},{"aid":"d","answer":"Molto adeguata"}],"answer":"a"},{"qid":2,"question":"Consapevolezza delle proprie difficoltà","answers":[{"aid":"a","answer":"Non adeguata"},{"aid":"b","answer":"Poco adeguata"},{"aid":"c","answer":"Adeguata"},{"aid":"d","answer":"Molto adeguata"}],"answer":"a"},{"qid":3,"question":"Consapevolezza dei propri punti di forza","answers":[{"aid":"a","answer":"Non adeguata"},{"aid":"b","answer":"Poco adeguata"},{"aid":"c","answer":"Adeguata"},{"aid":"d","answer":"Molto adeguata"}],"answer":"a"},{"qid":4,"question":"Regolarità frequenza scolastica","answers":[{"aid":"a","answer":"Non adeguata"},{"aid":"b","answer":"Poco adeguata"},{"aid":"c","answer":"Adeguata"},{"aid":"d","answer":"Molto adeguata"}],"answer":"a"},{"qid":5,"question":"Accettazione e rispetto delle regole","answers":[{"aid":"a","answer":"Non adeguata"},{