INSERT INTO utente_backup VALUES(960,1726928143631,1759915587479,1,'STUDENTE','Alessia ledy','Huaman huacac','Torino ','TO',1254528000000,'HMNLSL09R43L219U',NULL,'alessialedy.huamanhuacac@istitutoagnelli.it','3477309510','Via Guido Reni 10 10149 - TORINO (TO)',NULL,1,0,1,'ITT',5,NULL,0,NULL,0,'{"mipresento_nome":"Alessia Ledy Huaman Huaman","mipresento_anni":15,"mipresento_classe":"1 ITI B","mipresento_testo_1":"miei interessi sono giocare pallavolo, comporre, ascoltare musica \nle mie difficolta sono che non riesco a parlare davanati a i miei compagni, mi innervosisco perche ancora non parlo bene l''italiano","mipresento_testo_2":"sono soddisfatta quando prendo voti alti","mipresento_testo_3":"non mi piace che i miei compagnifanno troppo casino, mi sarebe di aiuto un po di amabilita da parte da i miei compagn, mi e'' difficile parlare ad alta voce e davanti a tutti","mipresento_testo_4":"vorrei poter abituarmi a la scuola, spero un po di compressione da parti degli insegnanti \n\n\n\n\n\n","mipresento_testo_5":"la musica\ncomporre canzioni\npallavolo\n\n\n\nandare in campagna\n\n\n\n","mipresento_testo_6":"nessuno","mipresento_testo_7":"amabilita\nresponsabilita\nvoglia di lavorare\n\n\n\n\n\n","mipresento_testo_8":"sono molto sensibile\nnon mi piace che mi prendano in giro o che mi facciano scherzi brutti\n\n\n","mipresento_testo_9":"un po di comprenssione\n\n\n\n"}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(961,1726928143632,1758278328957,1,'STUDENTE','Simone','Lazzarotto','Torino ','TO',1292889600000,'LZZSMN10T21L219Z',NULL,'simone.lazzarotto@istitutoagnelli.it','3477515252','VIA MONTE GRAPPA 5 10020 - RIVA PRESSO CHIERI (TO)',NULL,1,0,1,'ITT',5,'[{"qid":1,"question":"Manifesta difficoltà di lettura/scrittura","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"b"},{"qid":2,"question":"Manifesta difficoltà di comprensione del testo","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"c"},{"qid":3,"question":"Manifesta difficoltà di espressione orale","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"b"},{"qid":4,"question":"Manifesta difficoltà logico/matematiche","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"c"},{"qid":5,"question":"Manifesta difficoltà nel rispetto delle regole","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"b"},{"qid":6,"question":"Manifesta difficoltà nel mantenere l’attenzione durante le spiegazioni","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"d"},{"qid":7,"question":"Svolge regolarmente i compiti a casa","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"d"},{"qid":8,"question":"Consegna gli schemi all''insegnante secondo le modalità concordate","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answe