INSERT INTO utente_backup VALUES(1003,1726928144161,1758278398873,1,'STUDENTE','Gabriele','Tosches','Torino ','TO',1205107200000,'TSCGRL08C10L219M',NULL,'gabriele.tosches@istitutoagnelli.it','3476921582','CORSO IV NOVEMBRE 10 10136 - TORINO (TO)',NULL,0,0,1,'LICEO',23,NULL,0,NULL,0,NULL,1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1004,1726928144171,1758278398907,1,'STUDENTE','Sofia','Carbone','Torino ','TO',1179792000000,'CRBSFO07E62L219D',NULL,'sofia.carbone@istitutoagnelli.it','3395358735','CORSO GIUSEPPE PARINI 15C 10024 - MONCALIERI (TO)',NULL,0,0,1,'LICEO',24,NULL,0,NULL,0,NULL,0,NULL,0,NULL,0,NULL,0);
INSERT INTO utente_backup VALUES(1005,1726928144244,1758278420400,1,'STUDENTE','Carla','Amore','Torino ','TO',1289865600000,'MRACRL10S56L219X',NULL,'carla.amore@istitutoagnelli.it','3492626622','VIA ROVERETO 73 10136 - TORINO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"Carla Amore","mipresento_anni":14,"mipresento_classe":"1 Liceo B","mipresento_testo_1":"Vorrei prendere bei voti, riuscire ad andare d''accordo con tutti e mi piace nuotare","mipresento_testo_2":"Quando prendo un bel voto dopo un duro lavoro","mipresento_testo_3":"Non mi piace quando non riesco a raggiungere i mie obiettivi, mi sarebbe d''aiuto riuscire a imparare a non distrarmi ogni due minuti","mipresento_testo_4":"Mi aspetto di prendere bei voti, di fare amicizia e avere un buon rapporto con gli insegnati","mipresento_testo_5":"Il nuoto","mipresento_testo_6":"Rari Nantes Torino ","mipresento_testo_7":"Determinazione","mipresento_testo_8":"Lavorare in gruppo, testardaggine","mipresento_testo_9":"Comprensione"}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1006,1726928144246,1758278420403,1,'STUDENTE','Giorgio','Artigiani','Torino ','TO',1266537600000,'RTGGRG10B19L219S',NULL,'giorgio.artigiani@istitutoagnelli.it','3478152538','VIA PALMIERI 55 10138 - TORINO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"Giorgio Artigiani","mipresento_anni":14,"mipresento_classe":"1 liceo B","mipresento_testo_1":"sono Giorgio Artigiani ho 14 anni mi piace lo sport e ho difficolta nell''espormi in pubblico","mipresento_testo_2":"Quando prendo un bel voto meritato","mipresento_testo_3":"Non mi piace studiare cose che non mi piacciono","mipresento_testo_4":"Mi aspetto delle persone leali e comprensive","mipresento_testo_5":"Mi piace il tennis, i videogiochi il calcio e il motorsport","mipresento_testo_6":"A nessuno","mipresento_testo_7":"Sono ginnastica e inglese","mipresento_testo_8":"Il parlare in pubblco","mipresento_testo_9":"Di essere comprensivi"}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1007,1726928144247,1758278420417,1,'STUDENTE','Ginevra','Bardelle','Torino ','TO',1286841600000,'BRDGVR10R52L219J',NULL,'ginevra.bardelle@istitutoagnelli.it','3397596068','Piazza Pertini 18 10092 - BEINASCO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"Ginevra Bardelle","mipresento_anni":14,"mipresento_classe":"1 liceo B","mipresento_testo_1":"Mi piace fare sport, ascoltare la musica e uscire con i miei amici. Faccio più difficoltà a studiare le materie dove devo ricordarmi a memoria gli argomenti, mentre mi ritrovo più facilitata nelle materie scientifiche.","mipresento_testo_2":"Sono soddisfatta quando capisco un argomento che non mi era chiaro all''inizio, quando prendo un bel voto nelle materie che trovo più difficili e quando raggiungo un mio obiettivo. Sto bene dopo essere stata con i miei amici e dopo aver fatto sport.","mipresento_testo_3":"Mi è difficile trovare tempo per tutto e dover scegliere tra le varie cose che devo fare.","mipresento_testo_4":"Vorrei avere più tempo per andare fuori anche in settimana nonostante lo studio e i compiti. Mi aspetto collaborazione e sostegno come sta già succedendo ora.","mipresento_testo_5":"Mi piace ascoltare la musica, andare a nuoto o in palestra, guardare serie TV e film e uscire con gli amici.","mipresento_testo_6":"A nessuno.","mipresento_testo_7":"So ascoltare, mantengo i segreti e aiuto in caso di bisogno.","mipresento_testo_8":"A volte sono un po'' testarda e mi agito quando ho troppe cose da fare.","mipresento_testo_9":"Meno interrogazione e verifiche tutte nello stesso periodo."}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1008,1726928144249,1758278420421,1,'STUDENTE','Giorgia','Biglia','Torino ','TO',1285632000000,'BGLGRG10P68L219S',NULL,'giorgia.biglia@istitutoagnelli.it','3494989659','Via Poirino 10 10134 - TORINO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"Giorgia Biglia","mipresento_anni":14,"mipresento_classe":"1 liceo B","mipresento_testo_1":"Scienze, matematica, storia, arte, epica sono tutte materie che mi piacciono molto, mentre fisica e geography  mi piacciono ma faccio più fatica sia perché sono nuove sia perché sto trovando delle difficoltà.","mipresento_testo_2":"Sono soddisfatta quando con il mio impegno ottengo buoni voti.","mipresento_testo_3":"Non mi piacciono le incomprensioni, le liti, i mancati chiarimenti e quando mi impegno in quello che faccio e (a parte un brutto voto) non riesco a rendere per quanto ho studiato.","mipresento_testo_4":"Spero di riuscire bene in quello che faccio perché mi impegno sempre.","mipresento_testo_5":"Mi piace leggere, ascoltare musica, praticare apnea, nuotare, giocare ai videogiochi e disegnare.","mipresento_testo_6":"Non partecipo a nessun gruppo scolastico.","mipresento_testo_7":"Sono gentile e so ascoltare le persone.","mipresento_testo_8":"Resto male quando non vengo capita o non riesco in quello che faccio.","mipresento_testo_9":"Mi piacerebbe essere capita di più perché a volte anche se mi spiego mi rendo conto che non mi comprendono come vorrei."}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1009,1726928144250,1758278420424,1,'STUDENTE','Marta','Boetti','Torino ','TO',1273968000000,'BTTMRT10E56L219J',NULL,'marta.boetti@istitutoagnelli.it','3384317412','Via Roma 3/3 10048 - VINOVO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"Marta Boetti","mipresento_anni":14,"mipresento_classe":"1 liceo B","mipresento_testo_1":"Suono il violoncello in una orchestra con dei miei compagni delle medie, mi imbarazzo facilmente. mi piace suonare e  ","mipresento_testo_2":"Io conosco l''ambiente dell''elementari perché andavo a scuola al virginia, ho fatto le medie qui, sempre all''Edoardo agnelli. e mi sono sempre trovata bene sia come compagni che come professori. ho deciso di continuare perché mi piace molto l''ambiente e il clima che si crea tra compagni e professori.","mipresento_testo_3":"Non sono molto brava a prendere appunti durante le lezioni e spesso mi dimentico dei pezzi di spiegazione. non sono molto brava in disegno tecnico ma sto cercando di migliorare","mipresento_testo_4":"vorrei essere promossa con otto ma vedo che nn è semplice come credevo. vorrei essere amica di tutti e che i professori capiscano le mie difficoltà in alcune materie.","mipresento_testo_5":"come ho già detto in precedenza suono il violoncello e mi piace disegnare e ascoltare musica.","mipresento_testo_6":"faccio un gruppo che si chiama io ci sto con dei miei ex compagni delle medie, suono in una orchestra e faccio MGS quando posso. ","mipresento_testo_7":"sono abbastanza brava a relazionarmi con gli altri e faccio amicizia abbastanza facilmente. sono molto attenta agli altri e cerco di aiutare tutti nel miglior modo possibile. sono simpatica e sono sempre disponibile per tutti se c''è bisogno.","mipresento_testo_8":"mi preoccupo del giudizio altrui e ho paura di mettermi in ridicolo davanti alle persone che non conosco ancora benissimo. sono un po'' cocciuta e prima che capisca una cosa bisogna dirmela trenta volte (ma ci sto lavorando), non sono molto capace ad organizzarmi bene.","mipresento_testo_9":"ai miei insegnanti chiedo di non caricarci troppo con i compiti perché, appunto, devo ancora imparare ad organizzarmi bene. "}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1010,1726928144252,1758278420427,1,'STUDENTE','Simone','Bolognesi','Napoli ','NA',1276646400000,'BLGSMN10H16F839A',NULL,'simone.bolognesi@istitutoagnelli.it','3283791430','CORSO GALILEO FERRARIS 137 10128 - TORINO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"simone bolognesi","mipresento_anni":14,"mipresento_classe":"1 liceo b","mipresento_testo_1":"sono uno studente sportivo che pratica calcio e le mie materie preferite sono informatica e matematica le mie difficolta e rimanere costante con gli studi\n","mipresento_testo_2":"quando vinco una partita e quando prendo un bel voto","mipresento_testo_3":"non mi piace svegliarmi presto la mattina mi è di aiuto una giornata scolastica relativamente corta mi e difficile seguire in classe alla prima ora","mipresento_testo_4":"vorrei che la mia media scolastica si alzi e che rimanga costante con gli studi mi aspetto che gli insegnanti che ci dividano bene le verifiche e i compiti, dai compagni un po'' di serietà","mipresento_testo_5":"i pratico calcio 4 volte a settimana e i miei hobby sono: giocare ai videogiochi e giocare a carte ","mipresento_testo_6":"nessuno","mipresento_testo_7":"i miei punti di forza sono l''esposizione e le materie scientifiche","mipresento_testo_8":"e l''italiano e i temi ","mipresento_testo_9":"domande su verifiche cose e che non capisco "}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1011,1726928144253,1758278420429,1,'STUDENTE','Federico','Bono','Torino ','TO',1287705600000,'BNOFRC10R22L219O',NULL,'federico.bono@istitutoagnelli.it','3395379869','Via Barletta 107 10136 - TORINO (TO)',NULL,0,0,1,'LICEO',26,NULL,0,NULL,0,'{"mipresento_nome":"Federico Bono","mipresento_anni":14,"mipresento_classe":"1 Liceo B","mipresento_testo_1":"Mi piace giocare ai videogiochi, guardare film e serie TV","mipresento_testo_2":"Sono soddisfatto quando non prendo insufficienze e accade qualcosa di bello","mipresento_testo_3":"non mi piace andare male ma mi aiuta a stimolarmi per andare meglio la prossima volta","mipresento_testo_4":"","mipresento_testo_5":"mi piace il tennis, i manga e i supereroi","mipresento_testo_6":"Faccio tennis alla Sisport il martedì dalle 16:00 alle 18:00","mipresento_testo_7":"","mipresento_testo_8":"","mipresento_testo_9":"pazienza"}',1,NULL,1,NULL,1,NULL,0);
INSERT INTO utente_backup VALUES(1012,1726928144255,1759315722631,1,'STUDENTE','Francesco','Borgarello','Torino ','TO',1286323200000,'BRGFNC10R06L219Q',NULL,'francesco.borgarello@istitutoagnelli.it','3393222333','VIA DELLA ROCCA 30 10123 - TORINO (TO)',NULL,1,0,1,'LICEO',26,'[{"qid":1,"question":"Manifesta difficoltà di lettura/scrittura","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"c"},{"qid":2,"question":"Manifesta difficoltà di comprensione del testo","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"b"},{"qid":3,"question":"Manifesta difficoltà di espressione orale","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"b"},{"qid":4,"question":"Manifesta difficoltà logico/matematiche","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"c"},{"qid":5,"question":"Manifesta difficoltà nel rispetto delle regole","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"b"},{"qid":6,"question":"Manifesta difficoltà nel mantenere l’attenzione durante le spiegazioni","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"c"},{"qid":7,"question":"Svolge regolarmente i compiti a casa","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer":"c"},{"qid":8,"question":"Consegna gli schemi all''insegnante secondo le modalità concordate","answers":[{"aid":"a","answer":"Mai"},{"aid":"b","answer":"Talvolta"},{"aid":"c","answer":"Spesso"},{"aid":"d","answer":"Sempre"}],"answer"